import java.util.Arrays;
import java.util.concurrent.*;

class Traveler {
    volatile boolean asleep = false;

    void tryToSleep() {
        while (!asleep) {
            countSomeSheep();
        }
    }

    void countSomeSheep() {
        System.out.println("Tallying lanterns...");
    }
}

public class Main {
    public static ExecutorService exec = Executors.newFixedThreadPool(2);
    private static Traveler traveler;

    public static void main(String[] args) {
        traveler = new Traveler();
        exec.submit(() -> traveler.tryToSleep());
        Thread mainThread = Thread.currentThread();
        exec.shutdown();
        while (!exec.isTerminated() || !traveler.asleep && mainThread == Thread.currentThread()) {
            try {
                Thread.sleep(10);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
        System.out.println("Traveler is now asleep.");
    }
}

