import java.util.*;
import java.util.concurrent.*;

class MysticMonkeys {
    private final Set<String> monkeyLabels;

    public MysticMonkeys() {
        this.monkeyLabels = new HashSet<>(Arrays.asList("Banana", "Coco", "Mango"));
    }

    public boolean hasLabel(String label) {
        return monkeyLabels.contains(label);
    }

    public List<String> getMonkeysAsList() {
        return new ArrayList<>(monkeyLabels);
    }

    private class LabelChecker implements Runnable {
        private final String label;
        private volatile boolean found = false;

        public LabelChecker(String label) {
            this.label = label;
        }

        @Override
        public void run() {
            synchronized (this) {
                if (hasLabel(label)) {
                    found = true;
                    notifyAll();
                }
                while (!found && monkeyLabels.size() > 0) {
                    try {
                        wait();
                    } catch (InterruptedException e) {}
                }
            }
        }
    }

    public List<String> findMonkeys(Collection<String> labels) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<List<String>>> futures = new ArrayList<>();
        for (String label : labels) {
            LabelChecker checker = new LabelChecker(label);
            futures.add(executor.submit(checker));
        }
        executor.shutdown();

        List<String> result = new ArrayList<>();
        for (Future<List<String>> future : futures) {
            try {
                List<String> foundMonkeys = future.get();
                if (!foundMonkeys.isEmpty()) {
                    result.addAll(foundMonkeys);
                }
            } catch (Exception e) {}
        }

        return result;
    }
}

