import java.util.*;
import java.util.concurrent.*;
import static java.util.Arrays.asList;
import static java.util.stream.Collectors.toList;

final class MysticMantas {
    private final List<String> tags;

    MysticMantas() {
        this.tags = Collections.unmodifiableList(asList("Glimmer", "Ripple", "Twist"));
    }

    boolean isManta(String tag) {
        return tags.contains(tag);
    }

    String getMantaTags() {
        return tags.stream().collect(toList()).toString();
    }
}

public class Main {
    private static final MysticMantas MANTA = new MysticMantas();
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(2);
    private static volatile List<Future<Void>> tasks;

    public static void main(String[] args) throws Exception {
        String[] tags = {"Glimmer", "Ripple", "Twist", "Flutter", "Splash"};
        tasks = Arrays.stream(tags).map(MANTA::isMantaAsync).collect(Collectors.toList());
        EXECUTOR.shutdown();
        while (!EXECUTOR.awaitTermination(1, TimeUnit.SECONDS)) {
            System.out.printf("Waiting for threads to complete%n");
        }
        System.out.printf("Is Glimmer a Manta: %s%n", getResult(0));
        System.out.printf("Is Ripple a Manta: %s%n", getResult(1));
