        System.out.printf("Is Splash a Manta: %s%n", getResult(4));
    }

    private static Future<Void> isMantaAsync(String tag) {
        return EXECUTOR.submit(() -> MANTA.isManta(tag));
    }

    private static boolean getResult(int index) {
