        return tags.contains(tag);
    }

    @Override
    public String toString() {
        return String.join(", ", tags);
    }
}

class MantaChecker implements Runnable {
    private final MysticMantas mysticMantas;
    private final String tag;
    private volatile boolean found = false;

    public MantaChecker(MysticMantas mysticMantas, String tag) {
        this.mysticMantas = mysticMantas;
        this.tag = tag;
    }

    @Override
    public void run() {
        synchronized (this) {
            if (mysticMantas.isManta(tag)) {
                found = true;
                notifyAll();
            }
        }

        try {
            wait();
        } catch (InterruptedException e) {
            // Ignore interruptions
        }
    }

    public boolean isFound() {
        return found;
    }
}

