    private static final MysticMantas mysticMantas = new MysticMantas();

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS - 1);

        List<MantaChecker> checkers = new ArrayList<>();
        for (String tag : Arrays.asList("Glimmer", "Ripple", "Twist", "Unknown")) {
            MantaChecker mantaChecker = new MantaChecker(mysticMantas, tag);
            executor.submit(mantaChecker);
            checkers.add(mantaChecker);
        }

        boolean allFound = true;
        for (MantaChecker mantaChecker : checkers) {
