import java.util.*;
import java.util.concurrent.*;
import static java.util.concurrent.TimeUnit.*;

class ParcelCount {
    final int capacity;
    int count;

    public ParcelCount(int capacity) {
        this.capacity = capacity;
        this.count = 0;
    }

    synchronized void take(int quantity) {
        if (quantity > capacity - count) throw new IllegalStateException("Not enough parcels");
        count += quantity;
    }

    synchronized int give() {
        if (count == 0) throw new IllegalStateException("No parcels");
        count--;
        return 1;
    }
}

class Locker implements Runnable {
    final String name;
    ReentrantLock lock;
    ParcelCount parcels;

    public Locker(String name, int capacity) {
        this.name = name;
        lock = new ReentrantLock();
        parcels = new ParcelCount(capacity);
    }

    @Override
    public void run() {
        while (true) {
            if (!lock.tryLock(50, MILLISECONDS)) continue;
            try {
                // simulate parcel generation or consumption by incrementing/decrementing parcels count
                parcels.take(new Random().nextInt(10));
                lock.unlock();
                break;
            } catch (Exception e) {
                lock.unlock();
            }
        }
    }
}

class MoveTask implements Runnable {
    final Locker source, target;
    final int quantity;
    final long timeout, delay;

    public MoveTask(Locker source, Locker target, int quantity, long timeout, long delay) {
        this.source = source;
        this.target = target;
        this.quantity = quantity;
        this.timeout = timeout;
        this.delay = delay;
    }

    @Override
    public void run() {
        if (!source.lock.tryLock(100, MILLISECONDS)) return;
        try {
            if (!target.lock.tryLock(100, MILLISECONDS)) {
                source.lock.unlock();
                return;
            }
            try {
                if (source.parcels.count < quantity) throw new NotEnoughItemsException();
                source.parcels.give(quantity);
                target.parcels.take(quantity);
                System.out.println("Moved " + quantity + " parcels from " + source.name + " to " + target.name);
            } catch (Exception e) {
                if (e instanceof NotEnoughItemsException) {
                    System.err.println(e.getMessage());
                } else {
                    throw e;
                }
            } finally {
                target.lock.unlock();
                source.lock.unlock();
            }
        } catch (Exception e) {
            source.lock.unlock();
        }
    }
}

