import static java.util.concurrent.TimeUnit.NANOSECONDS;

public class LLMC {
private static Random rnd = new Random();

public boolean transferMoney(Account fromAcct,
Account toAcct,
DollarAmount amount,
long timeout,
TimeUnit unit)
throws InsufficientFundsException, InterruptedException {
long fixedDelay = getFixedDelayComponentNanos(timeout, unit);
long randMod = getRandomDelayModulusNanos(timeout, unit);
long timeoutNanos = unit.toNanos(timeout);
long startTime = System.nanoTime();

while (true) {
if (fromAcct.lock.tryLock()) {
try {
if (toAcct.lock.tryLock()) {
try {
if (fromAcct.getBalance().compareTo(amount) < 0)
throw new InsufficientFundsException();
else {
fromAcct.debit(amount);
toAcct.credit(amount);
System.out.println("Transfer success: $" + amount.value + " from " + fromAcct.id + " to " + toAcct.id);
return true;
}
} finally {
toAcct.lock.unlock();
}
}
} finally {
fromAcct.lock.unlock();
}
}

if (System.nanoTime() - startTime >= timeoutNanos)
return false;

NANOSECONDS.sleep(fixedDelay + rnd.nextLong() % randMod);
}
}

private static final long DELAY_FIXED = MILLISECONDS.toNanos(1);
private static final long DELAY_RANDOM = MILLISECONDS.toNanos(10);

static long getFixedDelayComponentNanos(long timeout, TimeUnit unit) {
return DELAY_FIXED;
}

static long getRandomDelayModulusNanos(long timeout, TimeUnit unit) {
return DELAY_RANDOM;
}

