    private final ReentrantLock lock;

    public Container(int initialCapacity) {
        this.items = new ArrayList<>(initialCapacity);
        this.lock = new ReentrantLock();
    }

    public boolean tryLock() {
        return lock.tryLock();
    }

    public void lock() {
        lock.lock();
    }

    public void unlock() {
        lock.unlock();
    }

    public int getItemCount() {
        return items.size();
    }
}

class ElementCount extends Exception {}

class InsufficientElementsException extends RuntimeException {
    private static final long serialVersionUID = 1L;

    public InsufficientElementsException() { super("Insufficient elements in the origin container."); }
}

class SwapTask implements Runnable {
    private final Container origin, target;
    private final int count;
    private final long timeout;
    private final TimeUnit unit;

    public SwapTask(Container origin, Container target, int count, long timeout, TimeUnit unit) {
        this.origin = origin;
        this.target = target;
        this.count = count;
        this.timeout = timeout;
        this.unit = unit;
    }

    @Override
    public void run() {
        boolean acquiredOriginLock = false, acquiredTargetLock = false;

        while (!acquiredOriginLock || !acquiredTargetLock) {
            if (origin.tryLock()) {
                if (target.tryLock()) {
                    acquiredOriginLock = true;
                    acquiredTargetLock = true;

                    if (origin.getItemCount() < count) {
                        throw new InsufficientElementsException();
                    } else {
                        Collections.swap(origin.items, 0, target.items.size() - count);
                        origin.unlock();
                        target.unlock();
                        return;
                    }
                }
            }

            if (!acquiredOriginLock && !target.tryLock()) {
                acquireSleepAndTryAgain(target, timeout, unit);
            } else if (acquiredTargetLock && !origin.tryLock()) {
                acquireSleepAndTryAgain(origin, timeout, unit);
            }
        }

        origin.unlock();
        target.unlock();
    }

    private void acquireSleepAndTryAgain(Container container, long timeout, TimeUnit unit) {
        try {
            Thread.sleep((int)(Math.random() * timeout));
        } catch (InterruptedException e) {}
        container.lock();
    }
}

