 this.sourceBin = sourceBin;
 this.targetBin = targetBin;
 this.numWidgets = numWidgets;
 }

 @Override
 public void run() {
 while (true) {
 if (sourceBin.lock.tryLock(TIMEOUT, MILLISECONDS)) {
 try {
 if (targetBin.lock.tryLock(TIMEOUT, MILLISECONDS)) {
 try {
 if (sourceBin.widgetCount.hasEnoughWidgets(numWidgets)) {
 for (int i = 0; i < numWidgets; i++) {
 sourceBin.widgetCount.decrementCount();
 targetBin.widgetCount.incrementCount();
 System.out.printf("Move: %d widgets from %s to %s%n", numWidgets, sourceBin.name, targetBin.name);
 }
 } else {
 throw new NotEnoughWidgetsException();
 }
 } finally {
 targetBin.lock.unlock();
 }
 } finally {
 sourceBin.lock.unlock();
 }
 }

 private static void pause(long duration, TimeUnit unit) {
 try {
 Thread.sleep(duration * unit.toMillis(1));
 } catch (InterruptedException e) {
 }
 }

 private static long fixedDelay = 50;
