import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import static java.util.concurrent.TimeUnit.MILLISECONDS;
import static java.util.concurrent.TimeUnit.NANOSECONDS;

public class LLMC {
private static Random rnd = new Random();

public boolean transferMoney(Account fromAcct,
Account toAcct,
DollarAmount amount,
long timeout,
TimeUnit unit)
throws InsufficientFundsException, InterruptedException {
long fixedDelay = getFixedDelayComponentNanos(timeout, unit);
long randMod = getRandomDelayModulusNanos(timeout, unit);
long timeoutNanos = unit.toNanos(timeout);
long startTime = System.nanoTime();

while (true) {
if (fromAcct.lock.tryLock()) {
try {
if (toAcct.lock.tryLock()) {
try {
if (fromAcct.getBalance().compareTo(amount) < 0)
throw new InsufficientFundsException();
else {
fromAcct.debit(amount);
toAcct.credit(amount);
System.out.println("Transfer success: $" + amount.value + " from " + fromAcct.id + " to " + toAcct.id);
return true;
}
} finally {
toAcct.lock.unlock();
}
}
} finally {
fromAcct.lock.unlock();
}
}

if (System.nanoTime() - startTime >= timeoutNanos)
return false;

NANOSECONDS.sleep(fixedDelay + rnd.nextLong() % randMod);
}
}

private static final long DELAY_FIXED = MILLISECONDS.toNanos(1);
private static final long DELAY_RANDOM = MILLISECONDS.toNanos(10);

static long getFixedDelayComponentNanos(long timeout, TimeUnit unit) {
return DELAY_FIXED;
}

static long getRandomDelayModulusNanos(long timeout, TimeUnit unit) {
return DELAY_RANDOM;
}

static class DollarAmount implements Comparable<DollarAmount> {
final int value;

DollarAmount(int dollars) {
this.value = dollars;
}

public int compareTo(DollarAmount other) {
return Integer.compare(this.value, other.value);
}

public String toString() {
return "$" + value;
}
}

static class Account {
final Lock lock = new ReentrantLock();
private DollarAmount balance;
final String id;

Account(String id, DollarAmount initialBalance) {
this.id = id;
this.balance = initialBalance;
}

void debit(DollarAmount d) {
balance = new DollarAmount(balance.value - d.value);
}

void credit(DollarAmount d) {
balance = new DollarAmount(balance.value + d.value);
}

DollarAmount getBalance() {
return balance;
}
}

static class InsufficientFundsException extends Exception {
public InsufficientFundsException() {
super("Insufficient funds for transfer.");
}
}

public static void main(String[] args) throws InterruptedException {
Account accountA = new Account("A", new DollarAmount(100));
Account accountB = new Account("B", new DollarAmount(100));

LLMC dao = new LLMC();

Thread t1 = new Thread(() -> {
try {
boolean success = dao.transferMoney(accountA, accountB, new DollarAmount(20), 100, MILLISECONDS);
System.out.println("T1: Transfer " + (success ? "succeeded" : "failed"));
} catch (Exception e) {
e.printStackTrace();
}
});

Thread t2 = new Thread(() -> {
try {
boolean success = dao.transferMoney(accountB, accountA, new DollarAmount(30), 100, MILLISECONDS);
System.out.println("T2: Transfer " + (success ? "succeeded" : "failed"));
} catch (Exception e) {
e.printStackTrace();
}
});

t1.start();
t2.start();

t1.join();
t2.join();

System.out.println("Final balances:");
System.out.println("Account A: " + accountA.getBalance());
System.out.println("Account B: " + accountB.getBalance());
System.out.println("Total threads including main: 3");
}
}

