import java.util.*;
import java.util.concurrent.*;

public class ServerStatusBeforeSplit {
    private final Set<String> vehicles = new HashSet<>();
    private final Set<String> events = new HashSet<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public ServerStatusBeforeSplit() {}

    public void addUser(String u) {
        synchronized (this) {
            vehicles.add(u);
        }
    }

    public void addQuery(String q) {
        synchronized (this) {
            events.add(q);
        }
    }

    public void removeUser(String u) {
        synchronized (this) {
            vehicles.remove(u);
        }
    }

    public void removeQuery(String q) {
        synchronized (this) {
            events.remove(q);
        }
    }

    public static void main(String[] args) {
        ServerStatusBeforeSplit server = new ServerStatusBeforeSplit();
        List<Runnable> tasks = Arrays.asList(
                () -> {
                    for (int i = 0; i < 100; i++) {
                        server.addUser("user" + i);
                        server.addQuery("query" + i);
                        try { Thread.sleep(10); } catch (InterruptedException e) {}
                    }
                },
                () -> {
                    for (int i = 0; i < 100; i++) {
                        int randomIndex = new Random().nextInt(200);
                        server.removeUser("user" + randomIndex);
                        server.removeQuery("query" + randomIndex);
                        try { Thread.sleep(15); } catch (InterruptedException e) {}
                    }
                },
                () -> System.out.println("Vehicles: " + server.vehicles),
                () -> System.out.println("Events: " + server.events)
        );

        executor.submit(tasks.get(0));
        executor.submit(tasks.get(1));
        executor.submit(() -> {
            for (Runnable task : tasks.subList(2, tasks.size())) {
                try { Thread.sleep(50); } catch (InterruptedException e) {}
                executor.submit(task);
            }
        });

        executor.shutdown();
        while (!executor.isTerminated()) {}
    }
}

