import java.util.*;
import java.util.concurrent.*;

class ServerStatusBeforeSplit {
    private final Set<String> vehicles = new HashSet<>();
    private final Set<String> events = new HashSet<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public ServerStatusBeforeSplit() {}

    private void addOrRemove(String name, Set<String> set, Runnable task) {
        synchronized (this) {
            set.add(name);
        }
        executor.submit(() -> {
            try {
                Thread.sleep(100); // Simulate some work
                task.run();
            } catch (InterruptedException e) {}
        });
    }

    public synchronized void addUser(String u) {
        addOrRemove(u, vehicles, () -> System.out.println("Added user: " + u));
    }

    public synchronized void addQuery(String q) {
        addOrRemove(q, events, () -> System.out.println("Added query: " + q));
    }

    public synchronized void removeUser(String u) {
        vehicles.removeIf(vehicle -> vehicle.equals(u));
    }

    public synchronized void removeQuery(String q) {
        events.removeIf(event -> event.equals(q));
    }

    public static void main(String[] args) throws InterruptedException {
        ServerStatusBeforeSplit server = new ServerStatusBeforeSplit();

        Runnable addUserTask1 = () -> {
            for (int i = 0; i < 5; i++) server.addUser("Car" + i);
        };

        Runnable addQueryTask2 = () -> {
            for (int i = 0; i < 3; i++) server.addQuery("Event" + i);
        };

        Runnable removeUserTask3 = () -> {
            for (int i = 4; i >= 1; i--) server.removeUser("Car" + i);
        };

        Runnable removeQueryTask4 = () -> {
            for (int i = 2; i >= 0; i--) server.removeQuery("Event" + i);
        };

        executor.submit(addUserTask1);
        executor.submit(addQueryTask2);
        Thread mainThread = Thread.currentThread();
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.SECONDS);
        executor.submit(removeUserTask3);
        executor.submit(removeQueryTask4);
        executor.shutdown();
        mainThread.join();
    }
}

