class PublishingVehicleTracker implements Runnable {
 private final Map<String, Vehicle> vehicles;
 private final ConcurrentMap<String, Future<Void>> futures;
 private final ExecutorService executor = Executors.newFixedThreadPool(2);

 public PublishingVehicleTracker() {
 vehicles = new HashMap<>();
 futures = new ConcurrentHashMap<>();
 }

 @Override
 public void run() {
 while (true) {
 try {
 Thread.sleep(100L);
 } catch (InterruptedException e) {
 break;
 }
 synchronizeOnAllVehicles(() -> updateVehicleCoordinates());
 }
 }

 private synchronized void synchronizeOnAllVehicles(Runnable action) {
 final Set<String> keys = new HashSet<>(vehicles.keySet());
 for (String key : keys) {
 if (!futures.putIfAbsent(key, executor.submit(action))
 .isDone()) {
 try {
 futures.get(key).get();
 } catch (ExecutionException | InterruptedException e) {
 throw new RuntimeException(e);
 }
 }
 }
 }

 private void updateVehicleCoordinates() {
 vehicles.values().stream()
 .peek(vehicle -> {
 try {
 futures.remove(vehicle.getId());
 } catch (Exception ignored) {
 }
 })
 .forEach(vehicle -> vehicle.setPosition(new SafePoint(Math.random(), Math.random())));
 }

