 return Optional.ofNullable(vehicles.get(id));
 }

 public synchronized void refreshVehicleCoordinates(String id, SafePoint position) {
 final Vehicle vehicle = vehicles.putIfAbsent(id, new Vehicle(id, position));
 if (vehicle != null) {
 return;
 }
 throw new IllegalStateException("Vehicle not found: " + id);
 }
}

