    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public void publishPosition(String id, double x, double y) {
        synchronized (positions) {
            SafePoint point = new SafePoint(x, y);
            if (!positions.containsKey(id)) {
                positions.putIfAbsent(id, point);
            } else {
                throw new RuntimeException("Vehicle not found: " + id);
            }
        }
    }

    public Map<String, SafePoint> getPositions() {
        return Collections.unmodifiableMap(positions);
    }

