    private static Set<Phantom> driftingPhantoms = new HashSet<>();
    private static Queue<Phantom> phantomQueue = new LinkedBlockingQueue<>(50);

    public static void materialize() {
        driftingPhantoms.clear();
        Arrays.stream(new Phantom[100]).forEach(phantom -> {
            synchronized (phantomQueue) {
                try {
                    phantomQueue.put(phantom);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        });
    }

    public static class Harvester implements Runnable {
        @Override
        public void run() {
            while (true) {
                try {
                    Phantom phantom = phantomQueue.take();
                    synchronized (driftingPhantoms) {
                        driftingPhantoms.add(phantom);
