public class RuneGrimoire {

    private static ExecutorService executor = Executions.newFixedThreadPool(2);

    private static List<Rune> sortAndFilterCandidateRunes(List<Rune> candidates) {
        return candidates.stream()
                .sorted(Comparator.comparing(r -> r.constellation)
                        .thenComparing(r -> r.resonance))
                .collect(toList());
    }

    private static List<Harmony> createValidHarmonies(List<Rune> sortedCandidates) {
        List<Harmony> validHarmonies = new ArrayList<>();
        int size = sortedCandidates.size();

        for (int i = 0; i < size - 1; ++i) {
            Rune currentRune = sortedCandidates.get(i);
            for (int j = i + 1; j < size; ++j) {
                Rune nextRune = sortedCandidates.get(j);
                if (currentRune.constellation == nextRune.constellation &&
                        currentRune.resonance != nextRune.resonance) {
                    validHarmonies.add(new Harmony(Arrays.asList(currentRune, nextRune)));
                }
            }
        }
        return validHarmonies;
    }

    public static int channelTheGrimoire(List<Rune> candidateRunes) {
        List<Rune> sortedAndFilteredCandidates = sortAndFilterCandidateRunes(candidateRunes);
        List<Future<List<Harmony>>> harmonyFutures = new ArrayList<>();

        int size = sortedAndFilteredCandidates.size();
        for (int i = 0; i < Math.min(size / 2, 2); ++i) {
            int startIndex = i * (size / 2);
            List<Rune> halfCandidates = sortedAndFilteredCandidates.subList(startIndex, size);
            Callable<List<Harmony>> callable = () -> createValidHarmonies(halfCandidates);
            Future<List<Harmony>> future = executor.submit(callable);
            harmonyFutures.add(future);
        }

        List<List<Harmony>> validHarmoniesLists = new ArrayList<>();
        for (Future<List<Harmony>> future : harmonyFutures) {
            try {
                validHarmoniesLists.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        }

        List<Harmony> allValidHarmonies = Stream.of(validHarmoniesLists.stream().flatMap(Collection::stream).toArray(Harmony[]::new));
        return allValidHarmonies.size();
    }

