                new Rune(Rune.Constellation.STARS, Rune.Resonance.POSITIVE) :
                new Rune(Rune.Constellation.MOON, Rune.Resonance.NEGATIVE) :
                new Rune(Rune.Constellation.values()[i % 3], Rune.Resonance.values()[i % 2 == 0 ? 1 : 0]));

        Grimoire grimoire = new Grimoire();
        int harmoniesCount = channelTheGrimoire(Arrays.asList(runes));
        System.out.println("Number of valid harmonies formed: " + harmoniesCount);

        List<Harmony> allHarmonies = Stream.of(runes).collect(Collectors.groupingBy(r -> r, Collectors.counting())).entrySet().stream()
                .filter(e -> e.getValue() > 1 && e.getKey().resonance != Rune.Resonance.NEGATIVE || e.getKey().constellation == Rune.Constellation.MOON)
                .flatMapToInt(e -> IntStream.rangeClosed(0, e.getValue() - 1).map(i -> e.getKey().hashCode()))
                .distinct()
                .limit((int) Math.ceil(Math.log(runes.length) / Math.log(2))) // Ceiling logarithm is not supported in Java, so we use a workaround with the next largest integer
