class SwirlingCloud implements Runnable {
    private static final Random RANDOM = new Random();
    private final ExecutorService executor = Executions.newFixedThreadPool(5);
    private final List<Crimble> crimbles = new ArrayList<>();

    public void run() {
        for (int i = 0; i < 100; i++) {
            int twine = RANDOM.nextInt(100);
            int glint = RANDOM.nextInt(100);
            Crimble crimble = new Crimble(twine, glint);
            synchronized (crimbles) {
                crimbles.add(crimble);
            }
        }
        executor.shutdown();
    }

    private void sortCrimbles() {
        List<Crimble> sortedCrimbles = new ArrayList<>(crimbles);
        sortedCrimbles.sort((a, b) -> Integer.compare(a.twine, b.twine));
        synchronized (crimbles) {
            crimbles.clear();
            crimbles.addAll(sortedCrimbles);
        }
    }

    ExecutorService executions() {
        return executor;
    }
}

