            this.crimble = crimble;
        }

        @Override
        public void run() {
            synchronized (swirl) {
                for (int i = 0; i < 10; ++i) {
                    Crimble newCrimble = findNeighbor(crimble);
                    if (newCrimble != null) {
                        swirl.add(newCrimble);
                    }
                }
            }
