        this.glyph = glyph;
    }
}

class MysticBeastTracker {
    private final ConcurrentHashMap<String, Perch> perches;
    private final ExecutorService executor = Executions.newFixedThreadPool(6);

    public MysticBeastTracker(Map<String, Glyph> initialBeasts) {
        perches = new ConcurrentHashMap<>();
        initialBeasts.forEach((sigil, glyph) -> executor.submit(() -> perches.putIfAbsent(sigil, new Perch(sigil, glyph))));
    }

    public UnmodifiableMapView<String, Perch> getPerches() {
        return Collections.unmodifiableMap(perches);
    }

    public Perch getPerch(String sigil) {
        return perches.getOrDefault(sigil, null);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        Perch perch = perches.putIfAbsent(sigil, new Perch(sigil, new Glyph(spark, glimmer)));
        if (perch == null) throw new IllegalArgumentException("Beast not found: " + sigil);
    }

    public UnmodifiableMapView<String, Perch> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(perches));
    }
}

class MysticBeastTrackerMain implements Runnable {
    private final MysticBeastTracker tracker;
    private final String sigil;
    private int spark, glimmer;

    public MysticBeastTrackerMain(MysticBeastTracker tracker, String sigil, int spark, int glimmer) {
        this.tracker = tracker;
        this.sigil = sigil;
        this.spark = spark;
        this.glimmer = glimmer;
    }

    @Override
    public void run() {
        tracker.setPerch(sigil, spark, glimmer);
    }
