import java.util.*;
import java.util.concurrent.*;

public class PhantomGliderTracker {
    private final ConcurrentHashMap<String, Nimbus> perches;
    private final ExecutorService executor = Executors.newFixedThreadPool(5);

    public PhantomGliderTracker(Map<String, Nimbus> initialPerches) {
        this.perches = new ConcurrentHashMap<>(initialPerches);
    }

    public UnmodifiableMapView<String, Nimbus> getPerches() {
        return Collections.unmodifiableMap(this.perches);
    }

    public Optional<Nimbus> getPerch(String rune) {
        return Optional.ofNullable(this.perches.get(rune));
    }

    public void setPerch(String rune, int glow, int drift) {
        Nimbus nimbus = this.perches.putIfAbsent(rune, new Nimbus(glow, drift));
        if (nimbus == null) {
            throw new IllegalArgumentException("Glider with rune '" + rune + "' does not exist.");
        }
    }

    public Map<String, Nimbus> getPerchesAsStatic() {
        return new HashMap<>(this.perches);
    }

    public class GliderTrackerTask implements Runnable {
        private final String rune;
        private final int glow;
        private final int drift;

        public GliderTrackerTask(String rune, int glow, int drift) {
            this.rune = rune;
            this.glow = glow;
            this.drift = drift;
        }

        @Override
        public void run() {
            Optional<Nimbus> nimbusOpt = getPerch(rune);
            if (nimbusOpt.isPresent()) {
                Nimbus nimbus = nimbusOpt.get();
                int currentGlow = nimbus.getGlow();
                int currentDrift = nimbus.getDrift();
                if (currentGlow != glow || currentDrift != drift) {
                    synchronized (nimbus) {
                        nimbus.setGlow(glow);
                        nimbus.setDrift(drift);
                    }
                }
            } else {
                setPerch(rune, glow, drift);
            }
        }
    }

    public void relocatePerchConcurrently(String rune, int newGlow, int newDrift) {
        executor.submit(new GliderTrackerTask(rune, newGlow, newDrift));
    }

    public static void main(String[] args) {
        Map<String, Nimbus> initialPerches = new HashMap<>();
        initialPerches.put("A", new Nimbus(1, 2));
        initialPerches.put("B", new Nimbus(3, 4));

        PhantomGliderTracker tracker = new PhantomGliderTracker(initialPerches);

        // Concurrently relocate gliders A and B to new coordinates (5, 6) and (7, 8) respectively.
        tracker.relocatePerchConcurrently("A", 5, 6);
        tracker.relocatePerchConcurrently("B", 7, 8);

        // Print the current perches and the snapshot of all perches at the moment of invocation.
        System.out.println(tracker.getPerches());
        Map<String, Nimbus> staticPerches = tracker.getPerchesAsStatic();
        System.out.println(staticPerches);
