import java.util.ArrayList;
import java.util.Collections;
import java.util.ConcurrentHashMap;
import java.util.List;
import java.util.concurrent.*;

interface Talisman {
    void enchant();
}

interface SigilNode<T> extends Talisman {
    List<SigilNode<T>> getChildren();
    T computeResult();
}

class Grove implements SigilNode<List<Talisman>> {
    private final List<SigilNode<Talisman>> children;

    public Grove(List<SigilNode<Talisman>> children) {
        this.children = children;
    }

    @Override
    public List<SigilNode<Talisman>> getChildren() {
        return children;
    }

    @Override
    public List<Talisman> computeResult() {
        // Recursive calculation of talismans in each sigil node
        return collect(children, new ArrayList<>());
    }

    private List<Talisman> collect(List<SigilNode<Talisman>> nodes, List<Talisman> result) {
        for (SigilNode<Talisman> node : nodes) {
            result.addAll(node.computeResult());
            result.addAll(collect(node.getChildren(), new ArrayList<>()));
        }
        return result;
    }
}

class TalismanEnchanter implements Runnable, SigilNode<Talisman> {
    private final List<Talisman> talismans = new ArrayList<>();

    public TalismanEnchanter(List<Talisman> talismans) {
        this.talismans = talismans;
    }

    @Override
    public List<SigilNode<Talisman>> getChildren() {
        return Collections.emptyList();
    }

    @Override
    public void enchant() {
        // Enchant each talisman
        for (Talisman talisman : talismans) {
            talisman.enchant();
        }
    }

    @Override
    public List<Talisman> computeResult() {
        return talismans;
    }

    @Override
    public void run() {
        enchant();
    }
}

public class Main {
    private static ExecutorService executor = Executions.newFixedThreadPool(2);
    private static ConcurrentHashMap<Integer, List<Talisman>> results = new ConcurrentHashMap<>();

    public static void sequence(List<SigilNode<Talisman>> sigils) {
        for (SigilNode<Talisman> sigil : sigils) {
            sigil.enchant();
            results.put(sigil.hashCode(), sigil.computeResult());
        }
    }

    public static void parallel(List<SigilNode<Talisman>> sigils) {
        List<Future<List<Talisman>>> futures = new ArrayList<>();
        for (int i = 0; i < sigils.size(); i += 2) {
            List<SigilNode<Talisman>> sublist = sigils.subList(i, Math.min(sigils.size(), i + 2));
            futures.add(executor.submit(() -> enchant(sublist)));
        }

        for (Future<List<Talisman>> future : futures) {
            try {
                results.put(future.get().hashCode(), future.get());
            } catch (InterruptedException | ExecutionException e) {
                // Handle exceptions if necessary
            }
        }
    }

    private static List<Talisman> enchant(List<SigilNode<Talisman>> sigils) {
        if (sigils.isEmpty()) return Collections.emptyList();
        SigilNode<Talisman> root = sigils.get(0);
