import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

interface Talisman<T> {
    T activate();
}

interface SigilNode<T> extends Talisman<List<T>> {
    List<SigilNode<?>> getChildren();
}

class Leaf implements SigilNode<Void> {
    private final Void value;

    public Leaf(Void value) {
        this.value = value;
    }

    @Override
    public List<SigilNode<?>> getChildren() {
        return Collections.emptyList();
    }

    @Override
    public Void activate() {
        return value;
    }
}

class Node implements SigilNode<Void> {
    private final List<SigilNode<?>> children;

    public Node(List<SigilNode<?>> children) {
        this.children = children;
    }

    @Override
    public List<SigilNode<?>> getChildren() {
        return children;
    }

    @Override
    public Void activate() {
        // Recursively activate all children and collect their results using the parallel processing method
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<Void>> futures = new ArrayList<>();
        for (SigilNode<?> child : children) {
            Future<Void> future = executor.submit(child::activate);
            futures.add(future);
        }
        try {
            boolean allDone = false;
            long timeout = 10, remainingTime = timeout;
            while (!allDone && remainingTime > 0) {
                allDone = futures.stream().allMatch(Future::isDone);
                if (allDone) break;
                remainingTime -= TimeUnit.SECONDS.sleep(1).toMillis(1);
            }
            if (!allDone) throw new TimeoutException("Activation timeout exceeded");
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            throw new RuntimeException(e);
        } finally {
            executor.shutdownNow();
        }
        return null; // Node has no value of its own, but completes the activation process
    }
}

public class ConcurrentSummoning {

    public static <T> List<T> sequenceActivate(SigilNode<T> node) {
        if (node instanceof Leaf) return Collections.singletonList(((Leaf<?>) node).activate());
        List<T> results = new ArrayList<>();
        for (T talisman : node.activate()) results.addAll(talisman);
        for (SigilNode<?> child : node.getChildren()) {
            results.addAll(sequenceActivate((SigilNode<?>) child));
        }
        return results;
    }

    public static <T> List<T> parallelActivate(SigilNode<T> node, ExecutorService executor) {
        if (node instanceof Leaf) return Collections.singletonList(((Leaf<?>) node).activate());
        List<Future<List<T>>> futures = new ArrayList<>();
        for (SigilNode<?> child : node.getChildren()) {
            Future<List<T>> future = executor.submit(() -> parallelActivate((SigilNode<?>) child, executor));
            futures.add(future);
        }
        List<T> results = new ArrayList<>();
        try {
            boolean allDone = false;
            long timeout = 10, remainingTime = timeout;
            while (!allDone && remainingTime > 0) {
                allDone = futures.stream().allMatch(future -> future.isDone());
                if (allDone) break;
                remainingTime -= TimeUnit.SECONDS.sleep(1).toMillis(1);
            }
            if (!allDone) throw new TimeoutException("Activation timeout exceeded");
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException(e);
        }
        for (Future<List<T>> future : futures) {
            try {
                results.addAll(future.get());
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        }
        return results;
    }

    public static void main(String[] args) {
        List<SigilNode<?>> forest = List.of(
                new Leaf(null),
                new Node(List.of(
                        new Leaf(null),
                        new Node(List.of(new Leaf(null)))
                )),
                new Node(List.of(
                        new Node(List.of(
                                new Leaf(null),
                                new Leaf(null)
                        )),
                        new Node(List.of(new Leaf(null)))
                ))
        );

        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<?>> futures = List.of(futureForResult(() -> sequenceActivate(forest.get(0))),
                futureForResult(() -> parallelActivate(forest.get(1), executor)));
        try {
            boolean allDone = false;
            long timeout = 10, remainingTime = timeout;
            while (!allDone && remainingTime > 0) {
                allDone = futures.stream().allMatch(future -> future.isDone());
                if (allDone) break;
                remainingTime -= TimeUnit.SECONDS.sleep(1).toMillis(1);
            }
            if (!allDone) throw new TimeoutException("Activation timeout exceeded");
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            throw new RuntimeException(e);
        } finally {
            executor.shutdownNow();
        }
        for (Future<?> future : futures) {
            try {
                System.out.println("Sequential: " + sequenceActivate(forest.get(0)));
                System.out.println("Parallel: " + future.get());
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        }
    }

    private static <T> Future<? extends T> futureForResult(Runnable runnable) {
        return new Future<>() {
            @Override
            public boolean cancel(boolean mayInterruptIfRunning) {
                return false;
            }

            @Override
            public boolean isCancelled() {
                return false;
            }

            @Override
            public boolean isDone() {
                return true;
            }

            @Override
            public T get() throws InterruptedException, ExecutionException {
                runnable.run();
                return null; // Not used since this Future represents a side-effect-only computation
            }
        };
    }
}

