        this.vault2 = vault2;
    }

    @Override
    public void run() {
        long primaryLock = Math.abs(System.identityHashCode(vault1) > System.identityHashCode(vault2) ? System.identityHashCode(vault1) : System.identityHashCode(vault2));
        Object secondaryLock = (primaryLock == System.identityHashCode(vault1)) ? vault2 : vault1;

        synchronized (primaryLock) {
            synchronized (secondaryLock) {
                if (vault1.getGold() >= 10 && vault2.getGold() >= 10) {
                    vault1.lock();
                    vault2.lock();
                    try {
