    @Override
    public synchronized void lock() {
        while (locked) {
            try {
                wait();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        locked = true;
    }

    @Override
    public synchronized void unlock() {
        if (!locked) {
