    public synchronized void lock() {
        while (lockHolder != null && lockHolder != Thread.currentThread()) {
            try {
                wait();
            } catch (InterruptedException e) {}
        }
        lockHolder = Thread.currentThread();
    }

    @Override
    public synchronized void unlock() {
