import java.math.BigInteger;
import java.util.ConcurrentModificationException;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

final class VaultNode {
    private final BigInteger id;
    private final Queue<BigInteger> crystals = new LinkedList<>();
    private final Object lock = this;
    private volatile boolean lockedByAnother;

    public VaultNode(BigInteger id) {
        this.id = id;
    }

    public void addCrystal(BigInteger crystal) {
        synchronized (lock) {
            if (lockedByAnother) {
                lock.notifyAll();
                try {
                    lock.wait();
                } catch (InterruptedException e) {}
            }
            crystals.add(crystal);
        }
    }

    public BigInteger withdrawCrystal(BigInteger amount) throws InsufficientCrystalsException {
        synchronized (lock) {
            if (lockedByAnother) {
                lock.notifyAll();
                try {
                    lock.wait();
                } catch (InterruptedException e) {}
            }
            if (amount.compareTo(crystals.peek()) > 0) {
                throw new InsufficientCrystalsException();
            }
            BigInteger crystal = crystals.poll();
            lockedByAnother = false;
            return crystal;
        }
    }

    public void lock() {
        synchronized (lock) {
            if (!lockedByAnother) {
                lockedByAnother = true;
                return;
            }
            if (id.equals(lockedByAnother.hashCode())) {
                secondaryLock.notifyAll();
                try {
                    secondaryLock.wait();
                } catch (InterruptedException e) {}
            }
        }
    }

    public void unlock() {
        synchronized (lock) {
            if (!lockedByAnother || !id.equals(lockedByAnother.hashCode())) {
                throw new IllegalMonitorStateException();
            }
            lockedByAnother = false;
            secondaryLock.notifyAll();
        }
    }

    final Object secondaryLock = new Object();
}

final class CrystalAmount implements Comparable<CrystalAmount> {
    private final BigInteger amount;

