import java.util.ArrayDeque;
import java.util.ConcurrentModificationException;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.Semaphore;

class OrbVault {
    private final Semaphore orbSemaphore = new Semaphore(0);
    private final Semaphore slotSemaphore = new Semaphore(10);
    private final Queue<Orb> vault = new ArrayDeque<>();

    public OrbVault() throws InterruptedException {
        orbSemaphore.release();
        slotSemaphore.acquire();
    }

    public void put(Orb x) {
        try {
            slotSemaphore.acquire();
            vault.add(x);
            orbSemaphore.release();
        } catch (InterruptedException e) {
            // Handle interruption, if necessary
        }
    }

    public Orb take() {
        Orb orb;
        try {
            orbSemaphore.acquire();
            if (!vault.isEmpty()) {
                orb = vault.poll();
                slotSemaphore.release();
            } else {
                throw new IllegalStateException("Vault is empty");
            }
        } catch (InterruptedException | ConcurrentModificationException e) {
            // Handle interruption or concurrent modification, if necessary
        }
        return orb;
    }

    public boolean isEmpty() {
        synchronized (vault) {
            return vault.isEmpty();
        }
    }

    public boolean isFull() {
        synchronized (vault) {
            return vault.size() == 10;
        }
    }
}

