        for (int i = 0; i < 5; i++) {
            if (orb != null) {
                vault.put(orb);
                System.out.printf("Sorcerer %d placed orb%n", id);
            } else {
                Orb takenOrb = vault.take();
                System.out.printf("Sorcerer %d took orb %d%n", id, takenOrb.getId());
