class CircularBuffer {
    private static final int CAPACITY = 3;
    private Deque<Potion> buffer = new ArrayDeque<>(CAPACITY);
    private Semaphore potionSemaphore = new Semaphore(CAPACITY);
    private Semaphore slotSemaphore = new Semaphore(CAPACITY + 1);

