        try {
            slotSemaphore.acquire();
            if (buffer.isEmpty()) {
                potionSemaphore.acquire();
            }
            buffer.addLast(x);
        } catch (InterruptedException e) {
            System.err.println("Thread interrupted during put()");
        } finally {
            slotSemaphore.release();
        }
