                potion = buffer.removeFirst();
            }
        } catch (InterruptedException e) {
            System.err.println("Thread interrupted during take()");
        } finally {
            slotSemaphore.release();
            potionSemaphore.release();
        }
        return potion;
    }

    public boolean isEmpty() {
