import java.util.*;
import java.util.concurrent.*;

public class PotionLoop {
    private final int capacity;
    private final Semaphore emptySlots, filledPotions;
    private final BlockingQueue<Potion> loop;

    public PotionLoop(int capacity) {
        this.capacity = capacity;
        this.emptySlots = new Semaphore(capacity);
        this.filledPotions = new Semaphore(0);
        this.loop = new LinkedBlockingQueue<>(capacity);
    }

    public void put(Potion x) {
        try {
            emptySlots.acquire();
            loop.put(x);
            filledPotions.release();
        } catch (InterruptedException e) {
            // handle exception
        }
    }

    public Potion take() {
        Potion potion;
        try {
            filledPotions.acquire();
            potion = loop.take();
            emptySlots.release();
        } catch (InterruptedException e) {
            // handle exception
            potion = null;
        }
        return potion;
    }

    public boolean isEmpty() {
        return filledPotions.getQueueLength() == 0;
    }

    public boolean isFull() {
        return emptySlots.getQueueLength() == 0;
    }

    private class Alchemist implements Runnable {
        private final String name;
        private final Random rand;

        public Alchemist(String name) {
            this.name = name;
            this.rand = new Random();
        }

        @Override
        public void run() {
            while (true) {
                Potion potion = null;
                try {
                    if (!isFull()) {
                        potion = new Potion("Potion " + rand.nextInt());
                        put(potion);
                    }
                    if (!isEmpty()) {
                        potion = take();
                        // use the extracted potion here...
                    }
                } catch (InterruptedException e) {
                    // handle exception
                }
            }
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        PotionLoop potionLoop = new PotionLoop(3);

        Alchemist alchemist1 = potionLoop.new Alchemist("Alchemist 1");
        Alchemist alchemist2 = potionLoop.new Alchemist("Alchemist 2");

