import java.util.*;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.Executors;
import java.util.concurrent.locks.ReentrantReadWriteLock;

class Rune {
    private final String key;
    private Object value;

    public Rune(String key) {
        this.key = key;
    }

    public String getKey() {
        return key;
    }

    public void setValue(Object value) {
        this.value = value;
    }

    public Object getValue() {
        return value;
    }
}

class SigilLedger implements ConcurrentMap<String, Rune> {
    private final Map<String, Rune> runes;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public SigilLedger(Map<String, Rune> runes) {
        this.runes = new HashMap<>(runes);
    }

    @Override
    public int size() {
        lock.readLock().lock();
        try {
            return runes.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return runes.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public boolean containsKey(Object key) {
        lock.readLock().lock();
        try {
            return runes.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public boolean containsValue(Object value) {
        lock.readLock().lock();
        try {
            return runes.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public Rune get(Object key) {
        lock.readLock().lock();
        try {
            return runes.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public Rune put(String key, Rune value) {
        lock.writeLock().lock();
        try {
            return runes.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public Rune remove(Object key) {
        lock.writeLock().lock();
        try {
            return runes.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public void putAll(Map<? extends String, ? extends Rune> m) {
        lock.writeLock().lock();
        try {
            runes.putAll(m);
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public void clear() {
        lock.writeLock().lock();
        try {
            runes.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }
}

public class Main {
    private static final ExecutorService executor = Executors.newFixedThreadPool(4);
    private static SigilLedger ledger;

    public static void main(String[] args) throws InterruptedException {
        Map<String, Rune> initialRunes = new HashMap<>();
        initialRunes.put("A", new Rune("A"));
        initialRunes.put("B", new Rune("B"));
        ledger = new SigilLedger(initialRunes);

        executor.submit(() -> performInscription(ledger, "C", "C-run"));
        executor.submit(() -> performDivination(ledger));
        executor.submit(() -> performInscription(ledger, "D", "D-run"));
        executor.submit(() -> performDivination(ledger));

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);
    }

    private static void performInscription(SigilLedger ledger, String runeKey, String runeValue) {
        Rune rune = new Rune(runeKey);
        rune.setValue(runeValue);

        try {
            ledger.put(runeKey, rune);
        } catch (RuntimeException e) {
            System.err.println("Error during inscription: " + e.getMessage());
        }
    }

    private static void performDivination(SigilLedger ledger) {
        try {
            for (Rune rune : ledger.values()) {
                String runeValue = (String) rune.getValue();
                System.out.println("Diviner read: " + runeKey + ": " + runeValue);
            }
        } catch (RuntimeException e) {
            System.err.println("Error during divination: " + e.getMessage());
        }
    }
}

