public class Main {
    private static final Relic RELIC = Relic.INSTANCE;
    private static final ExecutorService executor = Executors.newFixedThreadPool(4);
    private static final ConcurrentlyCopiedArrayQueue<String> results = new ConcurrentlyCopiedArrayQueue<>(4);

    public static void main(String[] args) throws InterruptedException {
        int threadCount = 3;
        ExecutorService executor = Main.executor;
        Relic relic = RELIC;

        Callable<Void> allTasks = () -> {
            AtomicInteger completedThreads = new AtomicInteger(0);
            IntStream.range(0, threadCount).forEach(id -> {
                Future<?> future = executor.submit(new ThreadRunner(relic, id));
                results.offer(future.toString());
                CompletableFuture.runAsync(() -> {
