                        future.get();
                    } catch (Exception e) {
                        e.printStackTrace();
                    } finally {
                        completedThreads.incrementAndGet();
                    }
                });
            });
            return CompletableFuture.allOf(Arrays.stream(results.toArray()).map(str -> new StringTask(str)).toArray(StringTask[]::new));
        };

        CompletableFuture.runAsync(() -> {
            try {
                allTasks.get();
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                executor.shutdownNow();
                System.out.println("Ritual completion!");
            }
        });
    }

    static class StringTask implements Callable<Void> {
        private final String task;

        public StringTask(String task) {
            this.task = task;
        }

        @Override
        public Void call() throws Exception {
            executor.submit(() -> System.out.println("Finished Task: " + task));
            return null;
        }
    }
}

