class Constellation<K, V> {
    private Map<K, V> constellation;

    public Constellation(Map<K, V> constellation) {
        this.constellation = new HashMap<>(constellation);
    }

    private <T> T deepClone(Function<V, T> mapper) {
        return constellation.entrySet().stream()
                .collect(HashMap::new,
                        (m, e) -> m.put(e.getKey(), mapper.apply(e.getValue())),
                        Map::putAll);
    }

    public synchronized Constellation<K, V> getConstellations() {
        return new Constellation<>(deepClone(v -> v));
    }

    public synchronized V getOrb(K sigil) {
        return constellation.get(sigil);
    }

    public synchronized void setOrb(K sigil, int shimmerX, int shimmerY) {
        if (!constellation.containsKey(sigil)) {
            throw new IllegalArgumentException("Sigil not found.");
        }
        constellation.put(sigil, new MutableOrb(shimmerX, shimmerY));
    }
}

