class CelestialGriffinTracker implements Runnable {
    private final ScheduledExecutorService executor;
    private final StarlightMap<String> starlights;

    public CelestialGriffinTracker(StarlightMap<String> initialMap, long period, TimeUnit timeUnit) {
        this.starlights = new StarlightMap<>(initialMap);
        executor = Executors.newSingleThreadScheduledExecutor();
        executor.scheduleAtFixedRate(this, 0, period, timeUnit);
    }

    @Override
    public void run() {
        monitorGriffins();
    }

    private synchronized void monitorGriffins() {
        for (Map.Entry<String, MutableGem> entry : starlights.entrySet()) {
            MutableGem gem = entry.getValue();
            int newX = newRandomCoordinate(), newY = newRandomCoordinate();
            if (gem != null && !gem.getGlowX() == newX && gem.getGlowY() == newY) {
                gem.setGlowCoordinates(newX, newY);
            }
        }
    }

    private int newRandomCoordinate() {
        return ThreadLocalRandom.current().nextInt();
    }

