    }

    public synchronized void setGem(String rune, int x, int y) {
        MutableGem gem = starlights.putIfAbsent(rune, new MutableGem(rune));
        if (gem == null) {
            throw new IllegalArgumentException("Rune not found: " + rune);
        }
        gem.setGlowCoordinates(x, y);
    }
