        this.balance = initialBalance;
    }

    public BigDecimal getBalance() {
        return balance;
    }

    public boolean tryTransfer(Account destination, BigDecimal amount, long timeout, TimeUnit unit) throws InterruptedException {
        if (!lock.tryLock(timeout, unit)) return false;
        try {
            if (balance.compareTo(amount) < 0) throw new InsufficientFundsException();
            balance = balance.subtract(amount);
            destination.addAmount(amount);
            return true;
        } finally {
            lock.unlock();
