import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.*;

class BoundedBuffer<E> {
    private final int capacity;
    private final Queue<E> buffer = new LinkedList<>();
    private final Semaphore spaceAvailable;
    private final Semaphore itemsAvailable;

    public BoundedBuffer(int capacity) {
        this.capacity = capacity;
        this.spaceAvailable = new Semaphore(capacity);
        this.itemsAvailable = new Semaphore(0);
    }

    // Put an item into the buffer, blocking if necessary until space is available
    public void put(E x) throws InterruptedException {
        spaceAvailable.acquire();
        synchronized (buffer) {
            buffer.add(x);
        }
        itemsAvailable.release();
        buffer.notifyAll();
    }

    // Remove and return an item from the buffer, blocking if necessary until data is available
    public E take() throws InterruptedException {
        itemsAvailable.acquire();
        synchronized (buffer) {
            while (buffer.isEmpty()) {
                buffer.wait();
            }
            E x = buffer.poll();
        }
        spaceAvailable.release();
        buffer.notifyAll();
        return x;
    }

    // Check if the buffer is empty
    public boolean isEmpty() {
        synchronized (buffer) {
            return buffer.isEmpty();
        }
    }

    // Check if the buffer is full
    public boolean isFull() {
        synchronized (buffer) {
            return buffer.size() == capacity;
        }
    }
}

