import java.math.BigInteger;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class ConcurrentCacheServlet extends HttpServlet {

    private static final int NUM_THREADS = 2;
    private static final ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS + 1);
    private volatile ImmutableCache cache;

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        BigInteger input = new BigInteger(req.getParameter("value"));
        if (cache == null || !cache.containsKey(input)) {
            Runnable task = () -> cache = updateCache(input);
            executor.submit(task);
            resp.setStatus(HttpServletResponse.SC_ACCEPTED);
        } else {
            resp.getWriter().write(cache.get(input).toString());
        }
    }

    private ImmutableCache updateCache(BigInteger input) {
        List<BigInteger> result = new ArrayList<>();
        result.add(input);
        return new ImmutableCache(result);
    }

    private static class ImmutableCache {
        private final Map<BigInteger, List<BigInteger>> cache;

        private ImmutableCache(List<BigInteger> data) {
            this.cache = new HashMap<>();
            for (BigInteger key : data) {
                this.cache.put(key, data);
            }
        }

        public boolean containsKey(BigInteger key) {
            return cache.containsKey(key);
        }

        public List<BigInteger> get(BigInteger key) {
            return cache.get(key);
        }
    }

    @Override
    public void destroy() {
        executor.shutdownNow();
    }

    public static void main(String[] args) throws Exception {
        ConcurrentCacheServlet servlet = new ConcurrentCacheServlet();
        JavaWebUtils.runAsCatlet(servlet, 8080);
    }
}

