class RequestHandler implements Runnable {
    private final URI uri;
    private final BigInteger requestValue;
    private final ExecutorService executor = Executors.newSingleThreadExecutor();

    public RequestHandler(URI uri, BigInteger requestValue) {
        this.uri = uri;
        this.requestValue = requestValue;
    }

    @Override
    public void run() {
        try (HttpURLConnection conn = (HttpURLConnection) uri.toURL().openConnection()) {
            conn.setRequestMethod("GET");
            conn.connect();

            BigInteger[] cacheResult = Cache.getInstance().get(requestValue);
            if (cacheResult[0].equals(requestValue)) {
                System.out.println("Cache hit: " + requestValue);
            } else {
                BigInteger[] newResult = {requestValue, null};
                cacheResult = newResult;

                executor.submit(() -> {
                    Cache.getInstance().put(requestValue, newResult);
                    System.out.println("Cache updated: " + requestValue);
                });
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

