            t2.start();
        } else {
            resp.setStatus(HttpURLConnection.HTTP_NOT_FOUND);
        }

        executor().shutdownNow();
    }

    private ExecutorService executor() {
        return Executors.newSingleThreadExecutor();
    }
}

