import java.util.Arrays;
import java.util.concurrent.*;
import static java.lang.Thread.currentThread;
import static java.lang.StrictMath.ceil;
import static java.util.concurrent.TimeUnit.MILLISECONDS;
import static java.util.logging.Level.SEVERE;
import java.util.logging.Logger;
import java.util.function.Supplier;

class MyAppThread extends Thread {
    static final String DEFAULT_NAME = "MyAppThread";
    static final AtomicInteger counter = new AtomicInteger(0);
    static final Logger LOGGER = Logger.getLogger(MyAppThread.class.getName());
    static volatile boolean debugLifecycle = false;
    static final AtomicInteger totalCreated = new AtomicInteger();
    static final AtomicInteger alive = new AtomicInteger();

    MyAppThread() {
        super(DEFAULT_NAME + "_" + counter.getAndIncrement());
        totalCreated.incrementAndGet();
    }

    @Override
    public void run() {
        alive.incrementAndGet();
        if (debugLifecycle) {
            LOGGER.info(() -> String.format("%s created", getName()));
        }
        try {
            super.run();
        } catch (Throwable e) {
            handleException(e);
        } finally {
            alive.decrementAndGet();
            if (debugLifecycle) {
                LOGGER.info(() -> String.format("%s terminated", getName()));
            }
        }
    }

    private void handleException(Throwable e) {
        var msg = String.format("%s [%d] encountered an error: %s\n%s", getName(), currentThread().getId(), e.getClass().getSimpleName(), Arrays.toString(e.getStackTrace()));
        LOGGER.log(SEVERE, msg);
    }

    static int totalCreated() {
        return totalCreated.get();
    }

    static int alive() {
        return alive.get();
    }

    static void setDebug(boolean debug) {
        debugLifecycle = debug;
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        MyAppThread.setDebug(true);
        ExecutorService executor = Executors.newFixedThreadPool(5);
        Supplier<Runnable> taskSupplier = () -> new Runnable() {
            @Override
            public void run() {
                try {
                    Thread.sleep((int) (Math.random() * 300));
                } catch (InterruptedException e) {
                    MyAppThread.handleException(e);
                }
            }
        };
        for (int i = 0; i < 5; i++) {
            executor.submit(taskSupplier.get());
        }
        executor.shutdown();
        if (!executor.awaitTermination(1, MILLISECONDS)) {
            executor.shutdownNow();
        }
        System.out.printf("Total created: %d\n", MyAppThread.totalCreated());
        System.out.printf("Currently alive: %d\n", MyAppThread.alive());
    }
}

