import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Level;
import java.util.logging.Logger;

public class MyApp {
    private static final String DEFAULT_NAME = "MyAppThread";
    private static final AtomicInteger THREAD_ID = new AtomicInteger(0);
    private static final Logger LOGGER = Logger.getLogger(MyApp.class.getName());
    private static volatile boolean debugLifecycle = false;
    private static final AtomicInteger totalThreads = new AtomicInteger(1);
    private static final AtomicInteger aliveThreads = new AtomicInteger(0);

    public static class MyAppThread extends Thread {
        private final int id;
        private final Runnable task;

        public MyAppThread(Runnable task) {
            this(task, DEFAULT_NAME + "-" + THREAD_ID.getAndIncrement());
        }

        public MyAppThread(Runnable task, String name) {
            super(name);
            this.task = task;
            this.id = id;
        }

        @Override
        public void run() {
            aliveThreads.incrementAndGet();
            totalThreads.incrementAndGet();
            if (debugLifecycle) {
                LOGGER.log(Level.INFO, "Thread {0} created", this.getName());
            }
            try {
                task.run();
                if (debugLifecycle) {
                    LOGGER.log(Level.INFO, "Thread {0} terminated", this.getName());
                }
            } catch (Exception e) {
                String threadName = this.getName();
                LOGGER.log(Level.SEVERE, "Thread " + threadName + " encountered error: " + e.getMessage(), e);
            } finally {
                aliveThreads.decrementAndGet();
            }
        }
    }

    private static ExecutorService executor = new java.util.concurrent.Executors.FixedThreadPool(5);

    public static void main(String[] args) throws InterruptedException {
        List<Runnable> tasks = new ArrayList<>();
        for (int i = 0; i < 3; ++i) {
            tasks.add(() -> System.out.println("Task " + (i + 1)));
        }

        tasks.forEach(task -> executor.execute(new MyAppThread(task)));
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        LOGGER.log(Level.INFO, "Total threads created: {0}", totalThreads.get());
        LOGGER.log(Level.INFO, "Currently active threads: {0}", aliveThreads.get());
    }
}

