class MyThreadFactory implements ThreadFactory {
    private final ExecutorService threadPool;
    private final String poolName;
    private int threadCount = 0;

    public MyThreadFactory(String poolName, int corePoolSize) {
        this.poolName = poolName;
        this.threadPool = new ThreadPoolExecutor(corePoolSize, corePoolSize, 0L, TimeUnit.MILLISECONDS,
                new LinkedBlockingQueue<>());
    }

    @Override
    public Thread newThread(Runnable runnable) {
        Thread thread = new MyAppThread(runnable, poolName);
        if (threadCount < 5) { // limit to 5 additional threads beyond the main thread
