        this.locations = new ConcurrentHashMap<>(initialLocations);
        for (Map.Entry<String, Point> entry : initialLocations.entrySet()) {
            executor.submit(this);
            entry.setValue(null); // Prevent creating extra threads for already added vehicles
        }
