import java.util.*;
import java.util.concurrent.*;

public class PrimeGenerator {
    private static final int MAX_PRIMES = 10;
    private static final long GENERATION_DURATION = TimeUnit.SECONDS.toMillis(1);
    private volatile boolean isCancelled = false;
    private final List<Integer> primes = Collections.synchronizedList(new ArrayList<>());

    public void start() {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        executor.submit(() -> {
            try {
                generatePrimes();
            } finally {
                executor.shutdownNow();
            }
        });
    }

    public void cancel() {
        isCancelled = true;
    }

    private void generatePrimes() {
        for (int i = 2; !isCancelled && primes.size() < MAX_PRIMES; ++i) {
            if (!isPrime(i)) continue;
            synchronized (primes) {
                primes.add(i);
            }
        }
    }

    private boolean isPrime(int num) {
        if (num < 2) return false;
        for (int i = 2; i <= Math.sqrt(num); ++i) {
            if (num % i == 0) return false;
        }
        return true;
    }

    public List<Integer> getPrimes() {
        return primes;
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        PrimeGenerator generator = new PrimeGenerator();
        generator.start();
        Thread.sleep(GENERATION_DURATION);
        generator.cancel();
        List<Integer> primes = generator.getPrimes();
        System.out.println("Generated Primes: " + primes);
    }
}

