import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;

public class LLMC implements Runnable {

    private final List<BigInteger> primes =
            Collections.synchronizedList(new ArrayList<>());
    private final AtomicBoolean cancelled = new AtomicBoolean(false);
    private final int maxPrimes;

    public LLMC(int maxPrimes) {
        this.maxPrimes = maxPrimes;
    }

    @Override
    public void run() {
        BigInteger p = BigInteger.ONE;

        while (!cancelled.get() && sizeLessThanMax()) {
            p = p.nextProbablePrime();
            // synchronizedList ensures thread-safe add
            primes.add(p);

            try {
                Thread.sleep(10);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }

    private boolean sizeLessThanMax() {
        synchronized (primes) {
            return primes.size() < maxPrimes;
        }
    }

    public void cancel() {
        cancelled.set(true);
    }

    public List<BigInteger> getPrimes() {
        synchronized (primes) {
            return new ArrayList<>(primes);
        }
    }

    public static List<BigInteger> limitedPrimes() throws InterruptedException {
        LLMC generator = new LLMC(10);
        Thread thread = new Thread(generator);
        thread.start();

        Thread.sleep(1000); // let it run for 1s
        generator.cancel();

        thread.join();

        return generator.getPrimes();
    }

