import java.math.BigInteger;
import java.util.Arrays;
import java.util.ConcurrentMap;
import java.util.ConcurrentHashMap;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.TimeUnit;

class FactorCache {
    private final BigInteger number;
    private final BigInteger[] factors;
    private static final ConcurrentMap<BigInteger, FactorCache> cache = new ConcurrentHashMap<>();
    private static final ExecutorService executor = Executors.newFixedThreadPool(2);

    private FactorCache(BigInteger number) {
        this.number = number;
        factors = factorize(number).stream()
                .sorted((a, b) -> a.compareTo(b))
                .toArray(BigInteger[]::new);
    }

    private static Queue<BigInteger> factorize(BigInteger n) {
        Queue<BigInteger> factors = new LinkedList<>();
        for (BigInteger i = BigInteger.ONE; i.compareTo(n) <= 0; i = i.nextProbablePrime()) {
            if (n.mod(i).equals(BigInteger.ZERO)) {
                factors.add(i);
                n = n.divide(i);
            } else {
                break;
            }
        }
        factors.add(n);
        return factors;
    }

    public static FactorCache getOrCompute(BigInteger number) {
        FactorCache cacheEntry = cache.get(number);
        if (cacheEntry != null) {
            return cacheEntry;
        }

        Runnable task = () -> cache.putIfAbsent(number, new FactorCache(number));
        executor.submit(task);

        FactorCache result;
        do {
            result = cache.get(number);
        } while (result == null);

        return result;
    }

    public BigInteger[] getFactors() {
        return factors.clone();
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        FactorCache num1 = FactorCache.getOrCompute(BigInteger.valueOf(3));
        System.out.println(Arrays.toString(num1.getFactors()));

        FactorCache num2 = FactorCache.getOrCompute(BigInteger.valueOf(8));
        System.out.println(Arrays.toString(num2.getFactors()));

        FactorCache num3 = FactorCache.getOrCompute(BigInteger.valueOf(15));
        System.out.println(Arrays.toString(num3.getFactors()));

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    }
}

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Arrays;
