import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class FactorCache {
    private final BigInteger number;
    private final BigInteger[] factors;
    private static final Map<BigInteger, FactorCache> cache = new HashMap<>();
    private static final ExecutorService executor = Executors.newFixedThreadPool(2);

    public FactorCache(BigInteger number) {
        this.number = number;
        if (number.compareTo(BigInteger.ONE) <= 0) {
            throw new IllegalArgumentException("Number must be greater than 1");
        }
        factors = getFactors(number);
    }

    private static BigInteger[] getFactors(BigInteger number) {
        List<BigInteger> factors = new ArrayList<>();
        BigInteger i = BigInteger.ONE;
        while (!i.equals(number)) {
            if (number.mod(i).compareTo(BigInteger.ZERO) == 0) {
                factors.add(i);
                number = number.divide(i);
            } else {
                i = i.add(BigInteger.ONE);
            }
        }
        return factors.stream().toArray(BigInteger[]::new);
    }

    public static FactorCache getOrComputeFactorCache(BigInteger number) {
        FactorCache factorCache = cache.get(number);
        if (factorCache == null) {
            synchronized (cache) {
                factorCache = cache.get(number);
                if (factorCache == null) {
                    factorCache = new FactorCache(number);
                    cache.put(number, factorCache);

                    Runnable task = () -> cache.putIfAbsent(number, factorCache);
                    executor.submit(task);
                }
            }
        }
        return factorCache;
    }
}

public class Main {
    public static void main(String[] args) throws InterruptedException {
        List<BigInteger> numbers = Arrays.asList(BigInteger.valueOf(2), BigInteger.valueOf(8), BigInteger.valueOf(15),
                BigInteger.valueOf(30), BigInteger.valueOf(45));

