        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
    }
}

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.ConcurrentLinkedQueue;
import java.util.List;
import java.util.Queue;
import java.util.function.Supplier;

class FactorCache {
    private final BigInteger number;
    private final BigInteger[] factors;

    public FactorCache(BigInteger number, BigInteger[] factors) {
        this.number = Objects.requireNonNull(number);
        this.factors = Arrays.copyOf(ObjectArrays.requireNonNull(factors), factors.length);
    }

    public BigInteger getNumber() {
        return number;
    }

    public BigInteger[] getFactors() {
        return factors.clone();
    }

    static class FactorFinder implements Runnable {
        private final Queue<FactorCache> cache;
        private final Supplier<BigInteger> numberSupplier;
        private List<FactorCache> results = new ArrayList<>();

        public FactorFinder(Queue<FactorCache> cache, Supplier<BigInteger> numberSupplier) {
            this.cache = Objects.requireNonNull(cache);
            this.numberSupplier = Objects.requireNonNull(numberSupplier);
        }

        @Override
        public void run() {
            while (true) {
                FactorCache cacheEntry = cache.poll();
                if (cacheEntry == null) break;

                BigInteger number = cacheEntry.getNumber();
                BigInteger[] factors = cacheEntry.getFactors();

                if (number.equals(numberSupplier.get())) {
                    results.add(cacheEntry);
                } else {
                    for (int i = 2; i < number.intValue(); ++i) {
                        BigInteger test = BigInteger.valueOf(i);
                        if (test.square(number.divide(test)).compareTo(BigInteger.ONE) == 0) {
                            cache.add(new FactorCache(number, Arrays.copyOf(factors, factors.length + 1)));
                            factors[factors.length - 1] = test;
                            break;
                        }
                    }
                }
            }
        }
    }

    public static FactorCache findFactors(BigInteger number, int threads) {
        if (number.equals(BigInteger.ONE)) return new FactorCache(number, new BigInteger[]{BigInteger.ONE});

        Queue<FactorCache> cache = new ConcurrentLinkedQueue<>();
        List<Thread> finderThreads = new ArrayList<>(threads - 1);
        finderThreads.add(new Thread(new FactorFinder(cache, () -> number)));

        for (int i = 0; i < threads - 1; ++i) {
            BigInteger testNumber = new BigInteger(2 + (int)(Math.random() * 3));
            finderThreads.add(new Thread(new FactorFinder(cache, () -> testNumber)));
        }

        for (Thread thread : finderThreads) {
            thread.start();
        }

        for (Thread thread : finderThreads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        if (!cache.isEmpty()) {
            FactorCache result = cache.poll();
            while (!result.getNumber().equals(number)) {
                result = cache.peek();
            }
            return result;
        }

        return null;
    }
}

public class Main {
    public static void main(String[] args) {
        List<BigInteger> numbers = Arrays.asList(
                BigInteger.valueOf(1), BigInteger.valueOf(2), BigInteger.valueOf(3), BigInteger.valueOf(4),
                BigInteger.valueOf(5), BigInteger.valueOf(6), BigInteger.valueOf(7), BigInteger.valueOf(8),
                BigInteger.valueOf(9), BigInteger.valueOf(10)
        );

        ExecutorService executor = Executors.newFixedThreadPool(3);

        for (BigInteger number : numbers) {
            Future<FactorCache> resultFuture = executor.submit(() -> FactorCache.findFactors(number, 2));
            try {
                FactorCache result = resultFuture.get();
                if (result != null) {
                    System.out.printf("%s: %s\n", number, Arrays.toString(result.getFactors()));
                } else {
                    System.out.println("Unable to find factors for " + number);
                }
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        }

        executor.shutdown();
    }
}

