                return true;
            }
            return false;
        }
    }

    @Override
    public boolean remove(Object o) {
        synchronized (lock) {
            if (list.remove(o)) {
                prune();
                return true;
            }
            return false;
        }
    }

    private void prune() {
        Node<E> current = list.get(0);
        while (current != null) {
            if (current.next == null) break;
            if (!list.contains(current.next.value)) {
                current.next = current.next.next;
            } else {
                current = current.next;
            }
        }
