            @Override
            public E previous() {
                if (!hasPrevious()) throw new NoSuchElementException();
                E value = current.value;
                current = current.next == null ? list.get(list.size() - 1) : current.next;
                synchronized (lock) {
                    return value;
                }
            }

            @Override
            public int nextIndex() {
                if (current != null && current.next == null) return list.size();
                int index = 0;
                for (Node<E> node = current; node != null; node = node.next) ++index;
                return index;
