    }

    public boolean putIfAbsent(E value) {
        synchronized (lock) {
            if (!list.contains(value)) {
                list.add(new Node<>(value));
                prune();
                return true;
            }
            return false;
        }
    }

    public void runPruneTask() {
        executor.scheduleAtFixedRate(() -> prune(), 0, 1, TimeUnit.SECONDS);
    }
