import java.util.ArrayDeque;
import java.util.concurrent.*;
import static java.util.concurrent.TimeUnit.*;

class Node {
    int item;
    volatile Node next;

    Node(int item) {
        this.item = item;
    }
}

public class ConcurrentStack {
    private final AtomicReference<Node> top = new AtomicReference<>();
    private static final int MAX_SIZE = 5;
    private final ArrayDeque<Integer> stackValues = new ArrayDeque<>();
    private ExecutorService executor;
    private Semaphore semaphore = new Semaphore(1);

    public ConcurrentStack() {
        top.set(new Node(-1));
    }

    void push(int item) {
        Node newNode = new Node(item);
        while (true) {
            Node currentTop = top.get();
            if (currentTop.next == null || stackValues.size() < MAX_SIZE) {
                newNode.next = currentTop.next;
                if (!top.compareAndSet(currentTop, newNode)) {
                    continue;
                }
                stackValues.addLast(item);
                break;
            }
        }
    }

    int pop() {
        if (stackValues.isEmpty()) {
            return -1;
        }
        while (true) {
            Node currentTop = top.get();
            if (currentTop.next != null) {
                stackValues.removeLast();
                Node nextNode = currentTop.next;
                if (top.compareAndSet(currentTop, nextNode)) {
                    break;
                }
            }
        }
        return stackValues.removeLast();
    }

    public void executeTasks() {
        executor = Executors.newFixedThreadPool(3);
        Runnable task = () -> {
            for (int i = 0; i < MAX_SIZE; ++i) {
                push(i);
            }
            for (int i = 0; i < MAX_SIZE; ++i) {
                pop();
                System.out.println("Popped: " + stackValues.peekLast());
            }
        };
        semaphore.drainPermits(3);
        for (int i = 0; i < 3; ++i) {
            executor.submit(task);
        }
    }

    public void shutdown() throws InterruptedException {
        executor.shutdown();
        if (!executor.awaitTermination(5, SECONDS)) {
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentStack stack = new ConcurrentStack();
        stack.executeTasks();
        semaphore.acquire(); // Wait for all tasks to start
        stack.shutdown();
        stack.semaphore.await(); // Wait for all tasks to complete
        System.out.println("All tasks completed");
    }
}

