import static java.util.stream.Collectors.toList;

class Node {
    int item;
    volatile Node next;

    Node(int item) {
        this.item = item;
    }
}

public class ConcurrentStack {
    private volatile Node top;
    private static final int THREAD_COUNT = 3;
    private static ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT + 1);

    public ConcurrentStack() {
        top = null;
    }

    public void push(int item) {
        Node newNode = new Node(item);
        if (top == null) {
            top = newNode;
        } else {
            Node current = top;
            while (current.next != null) {
                current = current.next;
            }
            current.next = newNode;
        }
    }

    public int pop() {
        if (isEmpty()) {
            throw new EmptyStackException();
        }
        int poppedItem = top.item;
        Node prevTop = top;
        top = top.next;
        prevTop.next = null;
        return poppedItem;
    }

    public boolean isEmpty() {
        return top == null;
    }

    public static void main(String[] args) throws InterruptedException {
        ConcurrentStack stack = new ConcurrentStack();
        List<Runnable> tasks = IntStream.range(0, THREAD_COUNT)
                .mapToObj(i -> () -> {
                    for (int j = 0; j < 5; j++) {
                        stack.push(i * 10 + j);
                    }
                    for (int j = 0; j < 5; j++) {
                        if (!stack.isEmpty()) {
                            System.out.println("Thread " + i + ": Popped: " + stack.pop());
                        } else {
                            System.out.println("Thread " + i + ": Stack is empty");
                        }
                    }
                })
                .collect(toList());

        executor.submit(() -> {
            for (Runnable task : tasks) {
                task.run();
            }
        });

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        System.out.println("All threads have finished.");
    }
}

