import java.util.*;
import java.util.concurrent.*;
import static java.util.stream.Collectors.*;

class VehicleLocation {
    private final String id;
    private final int x, y;

    public VehicleLocation(String id, int x, int y) {
        this.id = id;
        this.x = x;
        this.y = y;
    }

    public String getId() {
        return id;
    }

    public int getX() {
        return x;
    }

    public int getY() {
        return y;
    }
}

class DelegatingVehicleTracker {

    private final ConcurrentHashMap<String, VehicleLocation> locations;
    private final ExecutorService executor = Executions.newFixedThreadPool(2);

    public DelegatingVehicleTracker() {
        locations = new ConcurrentHashMap<>();
        populateInitialLocations();
    }

    private void populateInitialLocations() {
        locations.put("vehicle1", new VehicleLocation("vehicle1", 0, 0));
        locations.put("vehicle2", new VehicleLocation("vehicle2", 1, 1));
    }

    public void updateLocation(String id, int x, int y) {
        if (locations.containsKey(id)) {
            locations.replace(id, new VehicleLocation(id, x, y));
        }
    }

    public Map<String, VehicleLocation> getLiveLocations() {
        return Collections.unmodifiableMap(locations);
    }

    public Map<String, VehicleLocation> snapshotCurrentState() {
        return locations.entrySet().stream()
                .collect(toMap(Map.Entry::getKey, Map.Entry::getValue,
                        (e1, e2) -> e1, LinkedHashMap::new));
    }

    public void updateLocationConcurrently(String id, int x, int y) {
        Runnable runnable = () -> updateLocation(id, x, y);
        executor.submit(runnable);
    }
}

class Executions {
    static final ExecutorService newFixedThreadPool(int nThreads) {
        return Executors.newFixedThreadPool(Math.min(nThreads, 3));
    }
}

public class Main {

    public static void main(String[] args) throws InterruptedException {
        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker();

        // Get live locations and snapshot current state.
        Map<String, VehicleLocation> liveLocations = tracker.getLiveLocations();
        Map<String, VehicleLocation> snapshot = tracker.snapshotCurrentState();

        System.out.println("Initial Live Locations:");
        printVehicleLocations(liveLocations);

        System.out.println("\nInitial Snapshot Current State:");
        printVehicleLocations(snapshot);

        // Update locations concurrently using executor service.
        tracker.updateLocationConcurrently("vehicle1", 2, 2);
        tracker.updateLocationConcurrently("vehicle2", 3, 3);

        Thread.sleep(500); // Sleep to allow concurrent updates to complete.

        System.out.println("\nUpdated Live Locations:");
        printVehicleLocations(tracker.getLiveLocations());

        System.out.println("\nUpdated Snapshot Current State:");
        printVehicleLocations(snapshot);
    }

    private static void printVehicleLocations(Map<String, VehicleLocation> locations) {
        for (Map.Entry<String, VehicleLocation> entry : locations.entrySet()) {
            System.out.printf("%s: (%d, %d)\n", entry.getKey(),
                    entry.getValue().getX(), entry.getValue().getY());
        }
    }
}

