                } catch (IllegalStateException e) {
                    System.err.println(e.getMessage());
                }
            }
        }
    }

    public void startIncrementThreads() {
        for (int i = 0; i < THREAD_COUNT - 1; i++) {
            pool.submit(new IncrementTask());
        }
    }

    public void shutdown() {
        shutdownRequested.set(true);
        pool.shutdownNow();
    }

