public class SimulatedCAS {
    private volatile int value;
    private final ExecutorService exec = Executors.newSingleThreadExecutor();

    public int get() {
        synchronized (this) {
            return value;
        }
    }

    public int compareAndSwap(int expectedValue, int newValue) {
        synchronized (this) {
            if (value == expectedValue) {
                int old = value;
                value = newValue;
                return old;
            } else {
                return value;
            }
        }
    }

    public boolean compareAndSet(int expectedValue, int newValue) {
        return compareAndSwap(expectedValue, newValue) != value;
    }

    private void runConcurrentTask(Runnable task) {
        exec.submit(task);
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        SimulatedCAS cas = new SimulatedCAS();
        int expectedValue = 0;
        int newValue = 1;
        runnable = () -> {
            if (cas.compareAndSet(expectedValue, newValue)) {
                System.out.printf("Thread: %s - Successfully updated from %d to %d%n", Thread.currentThread().getName(), expectedValue, newValue);
            } else {
                System.out.printf("Thread: %s - Unable to update, current value is not %d%n", Thread.currentThread().getName(), expectedValue);
            }
        };

        Runnable runnable;
        Thread mainThread = Thread.currentThread();
        runConcurrentTask(() -> runnable = () -> cas.compareAndSwap(cas.get(), newValue));
        runConcurrentTask(() -> runnable.run());
        runnable.run();

        exec.shutdownNow();
        if (cas.compareAndSet(newValue, expectedValue)) {
            System.out.printf("%s - Successfully rolled back to initial value %d%n", mainThread.getName(), expectedValue);
        } else {
            System.out.printf("%s - Unable to roll back, current value is not %d%n", mainThread.getName(), newValue);
        }
    }
}

