import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

enum Gender { MALE, FEMALE }

class Animal {
    final String species;
    final Gender gender;

    Animal(String species, Gender gender) {
        this.species = species;
        this.gender = gender;
    }

    @Override
    public boolean equals(Object other) {
        if (other instanceof Animal) {
            Animal animal = (Animal) other;
            return species.equals(animal.species);
        }
        return false;
    }

    @Override
    public int hashCode() {
        return Objects.hash(species, gender);
    }
}

class AnimalPair {
    final Animal male;
    final Animal female;

    AnimalPair(Animal male, Animal female) {
        this.male = male;
        this.female = female;
    }
}

class Ark {
    private List<AnimalPair> pairs = new ArrayList<>();

    public void addPair(AnimalPair pair) {
        pairs.add(pair);
    }

    public int size() {
        return pairs.size();
    }
}

class AnimalLoader implements Runnable {
    private final SortedSet<Animal> animals;
    private final Ark ark;

    AnimalLoader(SortedSet<Animal> animals, Ark ark) {
        this.animals = animals;
        this.ark = ark;
    }

    @Override
    public void run() {
        for (int i = 0; i < 2; i++) {
            Animal first = animals.first();
            animals.remove(first);
            animals.stream().filter(another -> !another.equals(first))
                    .filter(animal -> first.gender != animal.gender && animal.species.equals(first.species))
                    .findFirst()
                    .ifPresent(second -> ark.addPair(new AnimalPair(first, second)));
        }
    }
}

public class ArkLoader {

    public static void main(String[] args) throws InterruptedException {
        Random random = new Random();
        List<Animal> animals = IntStream.range(0, 12)
                .mapToObj(i -> new Animal("Species_" + (random.nextInt(3)),
                        random.nextBoolean() ? Gender.MALE : Gender.FEMALE))
                .sorted(Comparator.comparing(Animal::species).thenComparing(Animal::gender))
                .collect(Collectors.toList());

        ExecutorService executor = Executions.newFixedThreadPool(3);
        Ark ark = new Ark();
        SortedSet<Animal> animalsBySpeciesAndGender = new TreeSet<>(comparingBySpeciesThenGender());
        animals.forEach(animalsBySpeciesAndGender::add);

        executor.invokeAll(Stream.generate(() -> new AnimalLoader(Collections.unmodifiableSortedSet(animalsBySpeciesAndGender), ark))
                .limit(2)
                .collect(Collectors.toList()));

        System.out.println("Number of valid pairs formed: " + ark.size());

        executor.shutdown();
    }

    private static Comparator<Animal> comparingBySpeciesThenGender() {
        Comparator<Animal> speciesComparator = Comparator.naturalOrder();
        Comparator<Animal> genderComparator = Comparator.comparing(animal -> animal.gender == Gender.MALE ? 0 : 1);
        return Comparator.comparing(animal -> speciesComparator.compare(animal, new Animal("NoSpecies", null)), genderComparator);
    }
}

