public class Main {

    private static final int THREAD_COUNT = 2;
    private static final long NANOSECONDS_PER_SECOND = 1_000_000_000L;

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT - 1);
        CountDownLatch startGate = new CountDownLatch(1);
        CountDownLatch endGate = new CountDownLatch(THREAD_COUNT);

        long startTime = System.nanoTime();
        Runnable taskLogic = () -> {
            try {
                startGate.countDown();
                startGate.awaitNanos(1, TimeUnit.MILLISECONDS); // Ensure synchronization before measuring the task time
                long localStart = System.nanoTime();

                // Task implementation with minimal loop iteration count (e.g., 2) and random number range (0-2)
                for (int i = 0; i < 2; i++) {
                    Thread.yield();
                    Random random = new Random();
                    int randomNumber = random.nextInt(3);
                }

                long localEnd = System.nanoTime();
                long taskDuration = localEnd - localStart;

                endGate.countDown();
                System.out.printf("Thread: %s, Task duration: %.9f seconds%n", Thread.currentThread().getName(), (double) taskDuration / NANOSECONDS_PER_SECOND);
            } catch (InterruptedException e) {
                // Preserve the interrupt status and exit the thread gracefully
                System.out.printf("Thread: %s, Interrupted%n", Thread.currentThread().getName());
                Thread.currentThread().interrupt();
            }
        };

        for (int i = 0; i < THREAD_COUNT - 1; i++) {
