        }
        executor.shutdown();
        startGate.await(); // Wait for all threads to start
        endGate.await(); // Wait for all threads to complete

        long endTime = System.nanoTime();
        double totalDuration = (double)(endTime - startTime) / NANOSECONDS_PER_SECOND;
        System.out.printf("Total duration: %.9f seconds%n", totalDuration);
    }
