public class PrimeProducerConsumer {

    private static final int NUM_PRIMES = 10;
    private static BlockingQueue<Integer> queue = new LinkedBlockingQueue<>(NUM_PRIMES * 2);
    private static ExecutorService executor = Executions.newFixedThreadPool(3);

    public static class PrimeProducer extends Thread {
        @Override
        public void run() {
            List<Integer> primes = new ArrayList<>();
            int count = 0;
            while (count < NUM_PRIMES || !interrupted()) {
                outer:
                for (int i = 2; i <= 100; i++) {
                    if (isPrime(i)) {
                        primes.add(i);
                        count++;
                        if (count == NUM_PRIMES) break outer;
                        try {
                            queue.put(i);
                        } catch (InterruptedException e) {
                            break;
                        }
                    }
                }
            }
            executor.shutdownNow();
        }

        private boolean isPrime(int n) {
            if (n < 2) return false;
            for (int i = 2; i <= Math.sqrt(n); i++) {
                if (n % i == 0) return false;
            }
            return true;
        }
    }

    public static class PrimeConsumer extends Thread {
        @Override
        public void run() {
            try {
                for (int prime : Iterables.limit(queue.iterator(), NUM_PRIMES)) {
                    System.out.println("Consumed prime: " + prime);
                }
            } catch (InterruptedException e) {}
        }
    }

    public static void main(String[] args) throws InterruptedException {
        PrimeProducer producer = new PrimeProducer();
        producer.start();
        executor.execute(new PrimeConsumer());
        producer.join();
        executor.shutdownNow();
    }
