        @Override
        public void run() {
            BigInteger current = BigInteger.ONE;
            for (int i = 0; i < NUM_PRIMES || isInterrupted(); i++) {
                while (!isPrime(current)) {
                    current = current.add(BigInteger.valueOf(2));
