            if (n.equals(BigInteger.ONE)) return false;
            for (BigInteger i = BigInteger.TWO; i.compareTo(n.sqrt()) <= 0; i = i.add(BigInteger.ONE)) {
                if (n.mod(i).equals(BigInteger.ZERO)) return false;
            }
            return true;
        }
    }

    public static class PrimeConsumer extends Thread {
        @Override
        public void run() {
            while (!queue.isEmpty()) {
                try {
                    BigInteger prime = queue.take();
                    System.out.println(prime);
                } catch (InterruptedException e) {
                    break;
                } catch (ConcurrentModificationException e) {
                    // Ignore potential exceptions due to producer thread interruption
                }
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
