import java.util.*;
import java.util.concurrent.*;

public class PrimeProducerConsumer {
    private static BlockingQueue<Integer> queue = new LinkedBlockingQueue<>(2);
    private static final int NUM_PRIMES_TO_PRODUCE = 3;
    private static ExecutorService executor = Executions.newFixedThreadPool(2);
    private static volatile boolean stopProducer = false;

    public static class PrimeProducer extends Thread {
        @Override
        public void run() {
            for (int i = 2; i < Integer.MAX_VALUE && !stopProducer; ++i) {
                if (isPrime(i)) {
                    try {
                        queue.put(i);
                        System.out.printf("Produced: %d%n", i);
                        if (queue.size() >= NUM_PRIMES_TO_PRODUCE) {
                            stopProducer = true;
                            break;
                        }
                    } catch (InterruptedException e) {
                        System.err.printf("Producer interrupted: %s%n", e.getMessage());
                        return;
                    }
                }
            }
        }
    }

    public static class PrimeConsumer extends Thread {
        @Override
        public void run() {
            try {
                for (int prime : queue) {
                    System.out.printf("Consumed: %d%n", prime);
                    if (!queue.isEmpty()) {
                        queue.take(); // Empty the queue to avoid unnecessary blocking
                    }
                }
            } catch (InterruptedException e) {
                System.err.printf("Consumer interrupted: %s%n", e.getMessage());
            }
        }
    }

    private static boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) throws InterruptedException {
        PrimeProducer producer = new PrimeProducer();
        PrimeConsumer consumer = new PrimeConsumer();
        executor.execute(producer);
        executor.execute(consumer);

        consumer.join();
        producer.interrupt();
        executor.shutdownNow();
        while (!executor.isTerminated()) {
            Thread t = executor.takeLastCompletingTask().get();
            if (t instanceof PrimeProducer) {
                System.out.printf("Producer completed: %s%n", t);
            }
        }
    }
}

