    private final Node<Object> node;
    private final Collection<Object> results = new ConcurrentHashMap<>();

    public Processor(Node<Object> node) {
        this.node = node;
    }

    @Override
    public void run() {
        processNode(node, results);
    }

    private void processNode(Node<Object> node, Collection<Object> results) {
        if (node instanceof Leaf) {
            results.add(node.getData());
        } else {
            for (Node<Object> child : node.getChildren()) {
                executeAsync(new Processor(child), results);
            }
        }
    }

    private void executeAsync(Runnable task, Collection<Object> results) {
        Executors.newFixedThreadPool(2).submit(task);
    }
}

