    public static void sequentialProcess(Node<Object> root, Collection<Object> results) {
        processNode(root, results);
    }

    private static void processNode(Node<Object> node, Collection<Object> results) {
        if (node instanceof Leaf) {
            results.add(node.getData());
        } else {
            for (Node<Object> child : node.getChildren()) {
                processNode(child, results);
            }
        }
    }

    public static void parallelProcess(Node<Object> root, Collection<Object> results) {
        ExecutorService executor = Executors.newFixedThreadPool(3);
        List<Processor> tasks = new ArrayList<>();

        for (Node<Object> child : root.getChildren()) {
            tasks.add(new Processor(child));
        }
        tasks.add(new Processor(root));

        for (Processor task : tasks) {
            executor.submit(task);
        }

        try {
            executor.shutdown();
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        results.addAll(executor.getTaskCount() - 1, executor.shutdownNow());
    }
}

