import java.util.concurrent.locks.*;

class ReadWriteMap<K, V> {
    private final Map<K, V> map;
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public ReadWriteMap(Map<K, V> map) {
        this.map = map;
    }

    public void put(K key, V value) {
        lock.writeLock().lock();
        try {
            map.put(key, value);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public V get(Object key) {
        lock.readLock().lock();
        try {
            return map.get(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void remove(Object key) {
        lock.writeLock().lock();
        try {
            map.remove(key);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public int size() {
        lock.readLock().lock();
        try {
            return map.size();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean isEmpty() {
        lock.readLock().lock();
        try {
            return map.isEmpty();
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsKey(Object key) {
        lock.readLock().lock();
        try {
            return map.containsKey(key);
        } finally {
            lock.readLock().unlock();
        }
    }

    public boolean containsValue(Object value) {
        lock.readLock().lock();
        try {
            return map.containsValue(value);
        } finally {
            lock.readLock().unlock();
        }
    }

    public void clear() {
        lock.writeLock().lock();
        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        Map<Integer, String> originalMap = new HashMap<>();
        for (int i = 0; i < 10; i++) {
            originalMap.put(i, "value_" + i);
        }
        ReadWriteMap<Integer, String> readWriteMap = new ReadWriteMap<>(originalMap);

        Runnable readerTask = () -> {
            for (int i = 0; i < 5; i++) {
                System.out.println(readWriteMap.get(i));
            }
        };

        Runnable writerTask1 = () -> {
            readWriteMap.put(11, "new_value_1");
        };

        Runnable writerTask2 = () -> {
            readWriteMap.remove(5);
        };

        executor.submit(readerTask);
        executor.submit(writerTask1);
        executor.submit(writerTask2);
        executor.shutdown();
    }
}

