    }

    public void clear() {
        lock.writeLock().lock();
        try {
            map.clear();
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void putAll(Map<? extends K, ? extends V> map) {
        lock.writeLock().lock();
        try {
            this.map.putAll(map);
        } finally {
            lock.writeLock().unlock();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(4);
        Map<Integer, String> map = new HashMap<>();
        map.put(1, "one");
        ReadWriteMap<Integer, String> readWriteMap = new ReadWriteMap<>(map);

        Runnable reader = () -> {
            for (int i = 0; i < 3; i++) {
                System.out.println("Reader reads: " + readWriteMap.get(1));
            }
        };

        Runnable writer = () -> {
            for (int i = 0; i < 2; i++) {
                readWriteMap.put(2, "two");
            }
        };

        executor.submit(reader);
        executor.submit(writer);
        executor.submit(reader);

        Thread.sleep(100); // Allow threads to run for a short period

        executor.shutdown();
    }
}

